                                  maxWidth: 160,
                                  overflow: 'hidden',
                                  textOverflow: 'ellipsis',
                                  whiteSpace: 'nowrap',
                                  verticalAlign: 'bottom',
                                }}
                              >
                                {group.device.desc}
                              </span>
                            </Tooltip>
                          )}
                        </div>
                      )}
                    </div>

                    <List
                      itemLayout="horizontal"
                      dataSource={group.alerts}
                      renderItem={(item: any) => {
                        const meta = ANOMALY_MAP[item.monitoring.anomaly] || { text: '未知异常', color: 'default' };
                        return (
