          <a
            key="edit"
            onClick={() => {
              setCreateChildParent(null);
              setEditing(row);
              setModalOpen(true);
            }}
          >
            编辑
          </a>
          <Popconfirm
            key="delete"
            title="确认删除该工作区域吗？"
            onConfirm={async () => {
              try {
                await deleteArea(row.id);
                message.success('删除成功');
                await loadRows();
              } catch (error) {
                message.error(toErrorMessage(error));
              }
            }}
          >
            <a style={{ color: '#ff4d4f' }}>删除</a>
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <PageContainer title="工作区域">
      <ProTable<AreaTreeRow>
        rowKey="id"
        search={{ labelWidth: 'auto' }}
        onSubmit={(values) => setQuery(values)}
        onReset={() => setQuery({})}
        loading={loading}
        columns={columns}
        dataSource={filteredTreeData}
        pagination={false}
        expandable={{
          childrenColumnName: 'children',
          defaultExpandAllRows: true,
          rowExpandable: (record) => !!(record.children && record.children.length > 0),
        }}
        options={{ reload: loadRows }}
        optionsRender={renderRefSafeTableOptions}
        toolBarRender={() => [
          <Button
            key="create"
            type="primary"
            onClick={() => {
              setEditing(null);
              setCreateChildParent(null);
              setModalOpen(true);
            }}
          >
            新建区域
          </Button>,
        ]}
      />

      <ModalForm<AreaFormValues>
        title={
          editing
            ? '编辑工作区域'
            : createChildParent
              ? `新建子区域（上级：${createChildParent.name}）`
              : '新建工作区域'
        }
        open={modalOpen}
        initialValues={
          editing
            ? {
                name: editing.name,
                description: editing.description,
                network: editing.network,
                ssid: editing.ssid,
                passwd: editing.passwd,
                parent_id: editing.parent_id || undefined,
              }
            : createChildParent
              ? {
                parent_id: createChildParent.id,
              }
              : {}
        }
        modalProps={{
          destroyOnHidden: true,
